package dev.eugheist.ttmodern;
final class XPDrainFocusWorldClientAudit {
 static boolean saved,checked,useKey,released;static int releasedAt;static net.minecraft.world.item.ItemStack held;static int total,level;static float progress;
 static void restore(net.minecraft.client.Minecraft mc){if(!saved)return;mc.options.keyUse.setDown(useKey);var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.stopUsingItem();p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,held);p.totalExperience=total;p.experienceLevel=level;p.experienceProgress=progress;p.giveExperiencePoints(0);p.inventoryMenu.broadcastChanges();saved=false;}
 static void tick(net.minecraft.client.Minecraft mc,int t){
  if(t==1440){useKey=mc.options.keyUse.isDown();mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());held=p.getMainHandItem().copy();total=p.totalExperience;level=p.experienceLevel;progress=p.experienceProgress;saved=true;p.totalExperience=0;p.experienceLevel=0;p.experienceProgress=0;p.giveExperiencePoints(90);var wand=new net.minecraft.world.item.ItemStack(dev.eugheist.tc4modern.WandParts.WAND.get());dev.eugheist.tc4modern.FociContent.setFocus(wand,new net.minecraft.world.item.ItemStack(XPDrainFocus.ITEM.get()));p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,wand);p.inventoryMenu.broadcastChanges();}).join();}
  if(t==1455){EnchanterClientAudit.check(mc.player.totalExperience==90&&dev.eugheist.tc4modern.FociContent.getFocusItem(mc.player.getMainHandItem()).is(XPDrainFocus.ITEM.get()),"native XP and focus inventory packets before use");var focus=dev.eugheist.tc4modern.FociContent.getFocusItem(mc.player.getMainHandItem());EnchanterClientAudit.check((mc.getItemColors().getColor(focus,0)&0xFFFFFF)==(XPDrainFocusClient.color()&0xFFFFFF),"native item tint follows original cycling focus color");mc.options.keyUse.setDown(true);mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);}
  if(t>=1480&&!released&&mc.player.totalExperience==0&&thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().allMatch(a->dev.eugheist.tc4modern.WandData.get(mc.player.getMainHandItem(),a)==500)){released=true;releasedAt=t;mc.options.keyUse.setDown(false);mc.gameMode.releaseUsingItem(mc.player);System.out.println("TT XP USE DIAGNOSTIC client XP="+mc.player.totalExperience+",using="+mc.player.isUsingItem()+",vis="+thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().map(a->a.getTag()+"="+dev.eugheist.tc4modern.WandData.get(mc.player.getMainHandItem(),a)).toList());mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());System.out.println("TT XP USE DIAGNOSTIC server XP="+p.totalExperience+",using="+p.isUsingItem()+",vis="+thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().map(a->a.getTag()+"="+dev.eugheist.tc4modern.WandData.get(p.getMainHandItem(),a)).toList());}).join();EnchanterClientAudit.check(mc.player.totalExperience==0&&thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().allMatch(a->dev.eugheist.tc4modern.WandData.get(mc.player.getMainHandItem(),a)==500),"natural use ticks and native packets convert90XP to5vis in all six primals");mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(p.totalExperience==0&&thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().allMatch(a->dev.eugheist.tc4modern.WandData.get(p.getMainHandItem(),a)==500),"authoritative charge has no duplicate client or creative free increment");}).join();}
  if(released&&!checked&&t>=releasedAt+20)mc.getSingleplayerServer().submit(()->{try{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(p.totalExperience==0&&thaumcraft.api.aspects.Aspect.getPrimalAspects().stream().allMatch(a->dev.eugheist.tc4modern.WandData.get(p.getMainHandItem(),a)==500),"released focus does not charge further");checked=true;System.out.println("TT XP DRAIN WORLD CLIENT AUDIT: ALL PASS (actual use packet/natural held ticks,90XP to6x5vis,inventory and experience synchronization,native cycling tint,no duplicate or post-release charge,restored fixture)");}finally{restore(mc);}}).join();
 }
}
